package trinary

import (
	"errors"
	"math"
)

var errInvalidTrinary = errors.New("invalid trinary number")

// ParseTrinary converts a trinary number, represented as a string
// (e.g. "102012"), to its decimal equivalent.
//
// The last place is the 1's place, the second to last is the 3's place,
// the third to last is the 9's place, and so on.
//
// Strings containing any symbol other than 0, 1, or 2, or whose value
// overflows int64, are considered invalid and return an error.
func ParseTrinary(arg string) (int64, error) {
	var result int64
	for _, r := range arg {
		if r < '0' || r > '2' {
			return 0, errInvalidTrinary
		}
		digit := int64(r - '0')
		if result > (math.MaxInt64-digit)/3 {
			return 0, errInvalidTrinary
		}
		result = result*3 + digit
	}
	return result, nil
}

